function page($title, $body, $config) {
    global $pdo;
    $user = !empty($_SESSION['user_id']); $admin = !empty($_SESSION['admin_id']);
    $unread = 0;
    if ($user) { $n=$pdo->prepare('SELECT COUNT(*) FROM notifications WHERE user_id=? AND read_at IS NULL'); $n->execute(array((int)$_SESSION['user_id'])); $unread=(int)$n->fetchColumn(); }
    $ok = get_flash('success'); $err = get_flash('error');
    $path = parse_url(isset($_SERVER['REQUEST_URI']) ? $_SERVER['REQUEST_URI'] : '/', PHP_URL_PATH);
    $notice = ($ok ? '<div class="notice success">'.e($ok).'</div>' : '').($err ? '<div class="notice error">'.e($err).'</div>' : '');
    if (strpos($path, '/admin') === 0 && $path !== '/admin/login') {
        $active = strpos($path, '/admin/orders') === 0 ? 'orders' : (strpos($path, '/admin/products') === 0 ? 'products' : (strpos($path, '/admin/articles') === 0 ? 'articles' : (strpos($path, '/admin/downloads') === 0 ? 'downloads' : (strpos($path, '/admin/temporary-subscription') === 0 ? 'temporary' : (strpos($path, '/admin/payment') === 0 ? 'payment' : (strpos($path, '/admin/tickets') === 0 ? 'tickets' : 'overview'))))));
        $nav = '<a class="admin-nav-item '.($active==='overview'?'active':'').'" href="/admin"><span>▦</span>工作概览</a><a class="admin-nav-item '.($active==='orders'?'active':'').'" href="/admin/orders"><span>▤</span>订单管理</a><a class="admin-nav-item '.($active==='products'?'active':'').'" href="/admin/products"><span>▣</span>套餐管理</a><a class="admin-nav-item '.($active==='articles'?'active':'').'" href="/admin/articles"><span>▤</span>文章管理</a><a class="admin-nav-item '.($active==='downloads'?'active':'').'" href="/admin/downloads"><span>⇩</span>软件下载</a><a class="admin-nav-item '.($active==='temporary'?'active':'').'" href="/admin/temporary-subscription"><span>↗</span>临时订阅</a><a class="admin-nav-item '.($active==='payment'?'active':'').'" href="/admin/payment"><span>￥</span>支付设置</a><a class="admin-nav-item '.($active==='tickets'?'active':'').'" href="/admin/tickets"><span>▤</span>售后工单</a>';
        echo '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.e($title).' - 管理后台</title><link rel="stylesheet" href="/assets/style.css"></head><body class="admin-body"><div class="admin-shell"><aside class="admin-sidebar"><a class="admin-brand" href="/admin"><span class="brand-mark">✦</span><span><b>云盾 VPN</b><small>ADMIN CONSOLE</small></span></a><div class="admin-label">工作空间</div><nav>'.$nav.'</nav><div class="admin-side-note"><b>人工交付提醒</b><p>付款确认后，请及时填写订阅信息完成发货。</p></div><div class="admin-profile"><span class="avatar">AD</span><span><b>'.e(isset($_SESSION['admin_name']) ? $_SESSION['admin_name'] : '管理员').'</b><small>超级管理员</small></span></div></aside><section class="admin-content"><header class="admin-topbar"><button class="admin-menu" type="button" onclick="document.body.classList.toggle(\'sidebar-open\')">☰</button><div class="breadcrumb"><span>管理后台</span><b>/</b><strong>'.e($title).'</strong></div><div class="admin-top-actions"><span class="admin-search">⌕　搜索订单编号...</span><span class="admin-greeting">今天也要高效处理订单</span></div></header><main class="admin-main">'.$notice.$body.'</main></section></div><script>document.querySelectorAll("[data-confirm]").forEach(function(e){e.addEventListener("click",function(t){if(!confirm(e.dataset.confirm))t.preventDefault()})})</script></body></html>'; return;
    }
    $publicClass = $path === '/products' ? ' class="products-page"' : ($path === '/' ? ' class="home-page"' : ($path === '/downloads' ? ' class="downloads-page"' : ($path === '/orders' ? ' class="orders-page"' : ($path === '/admin/login' ? ' class="admin-login-body"' : ''))));
    $publicNav = $path === '/' ? '<a class="home-nav-active" href="/">首页</a><a href="/products">套餐订购</a><a href="#benefits">每日公益节点</a><a href="/downloads">软件下载</a><a href="/articles">使用教程</a>'.($user?'<a href="/orders">我的订单</a><a href="/account">个人中心</a><a href="/notifications">通知'.($unread?' <b class="nav-badge">'.$unread.'</b>':'').'</a>':'') : '<a href="/">首页</a><a href="/products">套餐</a><a href="/downloads">软件下载</a><a href="/articles">使用教程</a>'.($user?'<a href="/orders">我的订单</a><a href="/tickets">售后工单</a><a href="/account">个人中心</a><a href="/notifications">通知'.($unread?' <b class="nav-badge">'.$unread.'</b>':'').'</a>':'');
    echo '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.e($title).' - '.e($config['app']['name']).'</title><link rel="stylesheet" href="/assets/style.css"></head><body'.$publicClass.'><nav><a class="brand" href="/"><span class="brand-shield">◇</span>云盾 VPN</a><div class="navlinks">'.$publicNav.($user?'<form method="post" action="/logout" class="inline"><input type="hidden" name="_csrf" value="'.e(Security::csrfToken()).'"><button>退出</button></form>':'<a class="pill" href="/login">登录</a>').($admin?'<a href="/admin">管理后台</a>':'').'</div></nav><main>'.$notice.$body.'</main><footer>人工确认付款 · 人工交付 · 请勿在公开场合分享交付信息</footer><script>document.querySelectorAll("[data-confirm]").forEach(function(e){e.addEventListener("click",function(t){if(!confirm(e.dataset.confirm))t.preventDefault()})})</script></body></html>';
}
function money($cents){return '¥'.number_format($cents/100,2);}
function status_text($s){$m=array('pending_payment'=>'待付款确认','pending_delivery'=>'待发货','delivered'=>'已发货','cancelled'=>'已取消','refunding'=>'退款中','refunded'=>'已退款');return isset($m[$s])?$m[$s]:$s;}
function order_timeline($events,$order){if(!$events){$events=array(array('description'=>'订单已创建。','created_at'=>$order['created_at'],'actor_type'=>'user'));if(!empty($order['paid_at']))$events[]=array('description'=>'付款已确认。','created_at'=>$order['paid_at'],'actor_type'=>'admin');if(!empty($order['delivered_at']))$events[]=array('description'=>'订单已发货。','created_at'=>$order['delivered_at'],'actor_type'=>'admin');if(!empty($order['cancelled_at']))$events[]=array('description'=>'订单已取消：'.$order['cancel_reason'],'created_at'=>$order['cancelled_at'],'actor_type'=>$order['cancelled_by_type']);if(!empty($order['refund_requested_at']))$events[]=array('description'=>'退款申请：'.$order['refund_reason'],'created_at'=>$order['refund_requested_at'],'actor_type'=>'user');if(!empty($order['refund_processed_at']))$events[]=array('description'=>'退款处理：'.$order['refund_reason'],'created_at'=>$order['refund_processed_at'],'actor_type'=>'admin');} $html='<section class="order-timeline"><h2>订单状态时间线</h2>';foreach($events as $event)$html.='<div class="timeline-item"><i></i><div><b>'.e($event['description']).'</b><small>'.e($event['created_at']).'</small></div></div>';return $html.'</section>';}
function post_csrf(){Security::checkCsrf(isset($_POST['_csrf'])?$_POST['_csrf']:null);}
function copy_subscription_script(){return '<script>document.querySelectorAll(".copy-subscription").forEach(function(button){button.addEventListener("click",function(){var target=document.getElementById(button.dataset.copyTarget);if(!target)return;var text=target.textContent;navigator.clipboard?navigator.clipboard.writeText(text).then(function(){button.textContent="已复制";setTimeout(function(){button.textContent="复制"},1600)}):button.textContent="请手动复制";});});</script>';}
function product_form($product, $action, $title){
    $p = $product ?: array('name'=>'','description'=>'','traffic'=>'','region'=>'','device_limit'=>1,'status'=>'draft','sort_order'=>0);
    $plans = isset($p['plans']) && $p['plans'] ? $p['plans'] : array(array('id'=>'','name'=>'月卡','duration_days'=>30,'price_cents'=>2999,'status'=>'active','sort_order'=>0));
    $planRows=''; foreach($plans as $i=>$plan){$planRows.='<div class="plan-row"><input type="hidden" name="plans['.$i.'][id]" value="'.(int)$plan['id'].'"><input name="plans['.$i.'][name]" value="'.e($plan['name']).'" placeholder="月卡 / 季卡 / 年卡" required><input type="number" name="plans['.$i.'][duration_days]" value="'.(int)$plan['duration_days'].'" min="1" max="36500" required><input type="number" name="plans['.$i.'][price]" value="'.number_format($plan['price_cents']/100,2,'.','').'" min="0.01" step="0.01" required><select name="plans['.$i.'][status]"><option value="active"'.($plan['status']==='active'?' selected':'').'>启用</option><option value="inactive"'.($plan['status']==='inactive'?' selected':'').'>下架</option></select><input type="number" name="plans['.$i.'][sort_order]" value="'.(int)$plan['sort_order'].'" min="0"><button type="button" class="plan-remove" title="移除方案">×</button></div>';}
    return '<div class="product-form-card"><div class="product-form-heading"><div><span class="admin-kicker">CATALOG / 套餐管理</span><h1>'.e($title).'</h1><p>基础套餐可以添加多个时长和价格方案。</p></div><a class="secondary-button" href="/admin/products">返回列表</a></div><form method="post" action="'.e($action).'">'.csrf_field().'<div class="product-form-grid"><div class="product-form-section"><h2>基本信息</h2><p>用户在套餐页会看到这些内容。</p><label>套餐名称 <em>*</em><input name="name" value="'.e($p['name']).'" maxlength="160" required placeholder="例如：体验套餐"></label><label>套餐描述 <em>*</em><textarea name="description" maxlength="5000" required placeholder="介绍套餐适合的使用场景">'.e($p['description']).'</textarea></label><div class="form-two"><label>流量规格 <em>*</em><input name="traffic" value="'.e($p['traffic']).'" maxlength="100" required placeholder="例如：100GB"></label><label>地区/线路 <em>*</em><input name="region" value="'.e($p['region']).'" maxlength="100" required placeholder="例如：香港 / 新加坡"></label></div></div><div class="product-form-section"><h2>设备与发布</h2><p>套餐上架后，用户可在多个方案中选择购买。</p><div class="form-two"><label>设备数 <em>*</em><input type="number" name="device_limit" value="'.(int)$p['device_limit'].'" min="1" max="999" required></label><label>排序值<input type="number" name="sort_order" value="'.(int)$p['sort_order'].'" min="0" max="999999"></label></div><label>发布状态<select name="status"><option value="draft"'.($p['status']==='draft'?' selected':'').'>草稿</option><option value="active"'.($p['status']==='active'?' selected':'').'>已上架</option><option value="inactive"'.($p['status']==='inactive'?' selected':'').'>已下架</option></select></label></div></div><div class="product-form-section plans-section"><div class="plans-heading"><div><h2>时长与价格方案</h2><p>例如月卡 30 天 ¥29.99、季卡 90 天、年卡 365 天 ¥288。</p></div><button type="button" class="secondary-button" id="add-plan">＋ 添加方案</button></div><div class="plan-head"><span>方案名称</span><span>有效期（天）</span><span>价格（元）</span><span>状态</span><span>排序</span><span></span></div><div id="plan-list">'.$planRows.'</div></div><div class="product-form-actions"><a class="secondary-button" href="/admin/products">取消</a><button class="button" type="submit">保存套餐</button></div></form></div><script>(function(){var list=document.getElementById("plan-list"),add=document.getElementById("add-plan");if(!list||!add)return;add.onclick=function(){var i=list.querySelectorAll(".plan-row").length,row=document.createElement("div");row.className="plan-row";row.innerHTML="<input type=\"hidden\" name=\"plans["+i+"][id]\" value=\"0\"><input name=\"plans["+i+"][name]\" placeholder=\"月卡 / 季卡 / 年卡\" required><input type=\"number\" name=\"plans["+i+"][duration_days]\" value=\"30\" min=\"1\" max=\"36500\" required><input type=\"number\" name=\"plans["+i+"][price]\" min=\"0.01\" step=\"0.01\" required><select name=\"plans["+i+"][status]\"><option value=\"active\">启用</option><option value=\"inactive\">下架</option></select><input type=\"number\" name=\"plans["+i+"][sort_order]\" value=\""+(i+1)+"\" min=\"0\"><button type=\"button\" class=\"plan-remove\">×</button>";list.appendChild(row);};list.onclick=function(e){if(e.target.classList.contains("plan-remove")){if(list.querySelectorAll(".plan-row").length>1)e.target.parentNode.remove();}};})();</script>';
}
