v></div></section><section class="home-feature-grid"><article class="home-benefit-card" id="benefits"><span class="home-label">每日更新</span><h2>今日公益节点</h2><time>▣　'.date('Y.m.d').'</time><p>我们每天整理优质的免费公益节点分享，帮助更多用户在不同网络环境下保持连接。点击查看今日更新，获取最新的公益节点与使用说明。</p><a class="button" href="#guide">▣　查看今日更新</a><small>这是一个文章入口，查看完整的节点信息与使用说明。</small></article><section class="home-plans-panel"><div class="home-section-heading"><div><h2>精选套餐</h2><span>多种套餐选择，满足不同场景的使用需求。</span></div><a href="/products">查看全部套餐　→</a></div><div class="home-plans-grid">'.$cards.'</div></section></section><section class="home-articles" id="guide"><div class="home-section-heading"><div><h2>最新文章</h2><span>实用的使用教程与网络知识，帮助你更好地使用云盾 VPN。</span></div><a href="/articles">查看更多文章　→</a></div><div class="home-article-grid">'.(function($articleRows){$html='';$arts=array('blue'=>'art-node','purple'=>'art-guide','orange'=>'art-help');foreach($articleRows as $article){$html.='<article><a class="home-article-link" href="/articles/'.(int)$article['id'].'"><div class="article-art '.(isset($arts[$article['cover_style']])?$arts[$article['cover_style']]:$arts['blue']).'">'.e(mb_substr($article['category'],0,1,'UTF-8')).'</div><div><span>'.e($article['category']).'</span><h3>'.e($article['title']).'</h3><p>'.e($article['summary']).'</p><small>▣　'.e(substr($article['published_at'],0,10)).'　　→</small></div></a></article>'; }return $html?:'<div class="empty">暂时还没有已发布文章。</div>';})($articleRows).'</div></section></div>' ;page('首页',$body,$config);});
$router->get('/products', function() use($config,$pdo){$ps=$pdo->query('SELECT * FROM products WHERE status="active" ORDER BY sort_order,id')->fetchAll();$cards='';foreach($ps as $p){$s=$pdo->prepare('SELECT * FROM product_plans WHERE product_id=? AND status="active" ORDER BY sort_order,id');$s->execute(array($p['id']));$plans=$s->fetchAll();if(!$plans)continue;$first=$plans[0];$planButtons='';foreach($plans as $i=>$plan)$planButtons.='<label class="purchase-plan"><input type="radio" name="plan_id" value="'.(int)$plan['id'].'" data-price="'.(int)$plan['price_cents'].'" data-days="'.(int)$plan['duration_days'].'" '.($i===0?'checked':'').'><span>'.e($plan['name']).'</span></label>';$category=mb_strpos($p['name'],'体验')!==false?'体验':(mb_strpos($p['name'],'畅享')!==false?'畅享':'其他');$cards.='<article class="purchase-card" data-category="'.e($category).'" data-name="'.e($p['name']).'"><div class="purchase-card-top"><div class="purchase-icon">✦</div><span class="purchase-badge">'.($p['sort_order']<=10?'入门推荐':'灵活选择').'</span></div><div class="purchase-region">'.e($p['region']).'</div><h2>'.e($p['name']).'</h2><p class="purchase-description">'.e($p['description']).'</p><div class="purchase-specs"><span>流量 '.e($p['traffic']).'</span><span>'.(int)$p['device_limit'].' 台设备</span><span>人工交付</span></div><div class="purchase-plan-label">选择购买期限</div><form class="purchase-form" method="get" action="/order-confirm"><input type="hidden" name="product_id" value="'.(int)$p['id'].'"><div class="purchase-plans">'.$planButtons.'</div><div class="purchase-footer"><div><strong class="purchase-price">'.money($first['price_cents']).'</strong><small class="purchase-duration"> / '.e($first['name']).'</small></div><button class="purchase-button" type="submit">立即选购 <span>↗</span></button></div></form></article>';}$body='<div class="purchase-wrap"><div class="purchase-breadcrumb"><a href="/">首页</a><span>/</span><strong>套餐订购</strong></div><div class="purchase-hero"><div><span class="eyebrow">CHOOSE YOUR PLAN</span><h1>找到适合你的连接方案</h1><p>套餐信息清晰呈现，选择期限后再确认价格与支付方式。</p><div class="purchase-points"><span>✓ 套餐与价格透明</span><span>✓ 订单进度可查</span><span>✓ 交付内容仅本人可见</span></div></div><div class="purchase-notice"><i>●</i> 人工配合交付 · 付款确认后约 10 分钟</div></div><div class="purchase-heading"><div><h2>精选套餐</h2><span>按使用需求选择方案</span></div><div class="purchase-filter"><button type="button" class="is-active" data-filter="all">全部</button><button type="button" data-filter="体验">体验</button><button type="button" data-filter="畅享">畅享</button></div></div><div class="purchase-grid">'.($cards?:'<div class="purchase-empty"><b>暂时没有可购买的套餐</b><span>请稍后再来查看最新方案。</span></div>').'</div><section class="purchase-steps"><div class="purchase-steps-intro"><span class="eyebrow">HOW IT WORKS</span><h2>购买流程</h2><p>简单三步，轻松完成订购</p></div><div class="purchase-step"><i>1</i><div><b>选择套餐</b><small>选择适合的套餐与购买期限</small></div></div><em>›</em><div class="purchase-step"><i>2</i><div><b>提交订单</b><small>确认方案并提交订单信息</small></div></div><em>›</em><div class="purchase-step"><i>3</i><div><b>人工确认与交付</b><small>付款确认后开始处理交付</small></div></div></section><section class="purchase-faq"><div class="purchase-faq-heading"><div><span class="eyebrow">FAQ</span><h2>常见问题</h2><p>你可能关心的问题</p></div><a href="/articles">查看使用教程　→</a></div><div class="purchase-faq-grid"><details><summary>付款后多久可以收到订阅信息？</summary><p>付款确认后通常会尽快处理，订单状态和交付信息会同步显示在订单详情中。</p></details><details><summary>一个账号可以在多少设备上使用？</summary><p>可使用设备数以所选套餐页面展示的设备限制为准。</p></details><details><summary>支持哪些支付方式？</summary><p>当前支持页面显示的在线支付方式，也可以按照订单提示等待人工确认。</p></details><details><summary>如果遇到问题，如何联系？</summary><p>请前往售后工单提交问题，我们会根据订单信息协助处理。</p></details></div></section></div><script>document.querySelectorAll(".purchase-card").forEach(function(card){var radios=card.querySelectorAll("input[name=plan_id]"),price=card.querySelector(".purchase-price"),duration=card.querySelector(".purchase-duration");radios.forEach(function(r){r.addEventListener("change",function(){price.textContent="¥"+(parseInt(r.dataset.price,10)/100).toFixed(2);duration.textContent=" / "+r.parentNode.querySelector("span").textContent;});});});var filters=document.querySelectorAll(".purchase-filter button"),cards=document.querySelectorAll(".purchase-card");filters.forEach(function(filter){filter.addEventListener("click",function(){filters.forEach(function(item){item.classList.remove("is-active")});filter.classList.add("is-active");var value=filter.dataset.filter;cards.forEach(function(card){card.hidden=value!=="all"&&card.dataset.category!==value;});});});</script>';page('套餐订购',$body,$config);});
$router->get('/products/{id}', function($id) use($config,$pdo){$s=$pdo->prepare('SELECT * FROM products WHERE id=? AND status="active"');$s->execute(array((int)$id));$p=$s->fetch();if(!$p){http_response_code(404);return page('不存在','<div class="empty">套餐不存在或已下架。</div>',$config);}$s=$pdo->prepare('SELECT * FROM product_plans WHERE product_id=? AND status="active" ORDER BY sort_order,id');$s->execute(array($p['id']));$plans=$s->fetchAll();if(!$plans)return page('暂不可购买','<div class="empty">此套餐暂无可购买的时长方案。</div>',$config);$options='';foreach($plans as $i=>$plan)$options.='<label class="plan-option"><input type="radio" name="plan_id" value="'.(int)$plan['id'].'" '.($i===0?'checked':'').' required><span><b>'.e($plan['name']).'</b><small>'.(int)$plan['duration_days'].' 天</small></span><strong>'.money($plan['price_cents']).'</strong></label>';$body='<div class="detail product-detail"><span class="eyebrow">'.e($p['region']).'</span><h1>'.e($p['name']).'</h1><p>'.e($p['description']).'</p><ul class="spec"><li>流量：'.e($p['traffic']).'</li><li>设备数：'.$p['device_limit'].' 台</li><li>预计交付：人工确认付款后约 10 分钟</li></ul><form method="get" action="/order-confirm"><input type="hidden" name="product_id" value="'.(int)$p['id'].'"><div class="plan-picker"><h2>选择套餐时长</h2>'.$options.'</div><button class="button" type="submit">确认所选方案</button></form></div>';page($p['name'],$body,$config);});
