$router->get('/orders', function() use($config,$pdo){$uid=Security::requireUser();$s=$pdo->prepare('SELECT o.*,d.expires_at AS delivery_expires_at FROM orders o LEFT JOIN delivery_records d ON d.order_id=o.id AND d.is_current=1 WHERE o.user_id=? ORDER BY o.id DESC');$s->execute(array($uid));$orders=$s->fetchAll();$total=count($orders);$pendingPayment=0;$pendingDelivery=0;$rows='';foreach($orders as $o){if($o['status']==='pending_payment')$pendingPayment++;if($o['status']==='pending_delivery')$pendingDelivery++;$expires=!empty($o['delivery_expires_at'])?strtotime($o['delivery_expires_at']):false;$countdown='待发货';$countdownClass='order-countdown-pending';$expiryDate='交付后显示';if($expires!==false){$seconds=$expires-time();if($seconds<=0){$countdown='已到期';$countdownClass='order-countdown-expired';}else{$days=(int)ceil($seconds/86400);$countdown='剩余 '.$days.' 天';$countdownClass=$days<=7?'order-countdown-warning':'order-countdown-active';}$expiryDate=date('Y-m-d H:i',$expires);}$rows.='<tr class="order-row" data-order-status="'.e($o['status']).'" data-order-no="'.e(strtolower($o['order_no'])).'"><td><a class="orders-number" href="/orders/'.e($o['order_no']).'">'.e($o['order_no']).'</a></td><td><b class="orders-product">'.e($o['product_name_snapshot']).'</b><small class="table-sub">'.e($o['plan_name_snapshot']).' · '.(int)$o['duration_days_snapshot'].'天</small></td><td class="orders-amount">'.money($o['total_amount_cents']).'</td><td><span class="orders-status orders-status-'.e($o['status']).'">'.e(status_text($o['status'])).'</span></td><td><span class="order-countdown '.$countdownClass.'"><b>'.e($countdown).'</b><small>'.e($expiryDate).'</small></span></td><td class="orders-created">'.e($o['created_at']).'</td><td><a class="orders-detail-link" href="/orders/'.e($o['order_no']).'">查看详情</a></td></tr>';}$body='<div class="orders-wrap"><header class="orders-hero"><span class="eyebrow">ORDER CENTER</span><h1>我的订单</h1><p>随时查看付款与交付进度。</p></header><section class="orders-stats"><button type="button" class="orders-stat-card" data-stat-filter="all"><span class="orders-stat-icon orders-stat-blue">▤</span><span><small>全部订单</small><b>'.$total.'</b></span><i>›</i></button><button type="button" class="orders-stat-card" data-stat-filter="pending_payment"><span class="orders-stat-icon orders-stat-orange">◷</span><span><small>待付款确认</small><b>'.$pendingPayment.'</b></span><i>›</i></button><button type="button" class="orders-stat-card" data-stat-filter="pending_delivery"><span class="orders-stat-icon orders-stat-sky">⇢</span><span><small>待发货</small><b>'.$pendingDelivery.'</b></span><i>›</i></button></section><section class="orders-panel"><div class="orders-toolbar"><div class="orders-filters"><button type="button" class="orders-filter is-active" data-filter="all">全部</button><button type="button" class="orders-filter" data-filter="pending_payment">待付款确认</button><button type="button" class="orders-filter" data-filter="pending_delivery">待发货</button><button type="button" class="orders-filter" data-filter="delivered">已发货</button></div><label class="orders-search"><span>⌕</span><input type="search" id="order-search" placeholder="搜索订单号" autocomplete="off"></label></div><div class="orders-table-wrap"><table class="orders-table"><thead><tr><th>订单号</th><th>套餐</th><th>订单金额</th><th>状态</th><th>到期时间</th><th>创建时间</th><th>操作</th></tr></thead><tbody>'.($rows?:'<tr class="orders-empty-row"><td colspan="7"><div class="orders-empty"><span>▤</span><b>暂无订单</b><small>下单后，订单进度会在这里显示。</small><a href="/products">浏览套餐　→</a></div></td></tr>').'</tbody></table><div class="orders-no-match" hidden>没有符合条件的订单。</div></div></section></div><script>(function(){var filters=document.querySelectorAll(".orders-filter"),rows=document.querySelectorAll(".order-row"),search=document.getElementById("order-search"),empty=document.querySelector(".orders-no-match"),active="all";function apply(){var query=(search.value||"").toLowerCase().trim(),visible=0;rows.forEach(function(row){var show=(active==="all"||row.dataset.orderStatus===active)&&(!query||row.dataset.orderNo.indexOf(query)!==-1);row.hidden=!show;if(show)visible++});empty.hidden=visible!==0||rows.length===0;}function setFilter(value){active=value;filters.forEach(function(button){button.classList.toggle("is-active",button.dataset.filter===value)});apply()}filters.forEach(function(button){button.addEventListener("click",function(){setFilter(button.dataset.filter)})});document.querySelectorAll(".orders-stat-card").forEach(function(card){card.addEventListener("click",function(){setFilter(card.dataset.statFilter)});});search.addEventListener("input",apply);})();</script>';page('我的订单',$body,$config);});
$router->get('/orders/{no}', function($no) use($config,$pdo){$uid=Security::requireUser();$service=new OrderService($pdo);$o=$service->getForUser($no,$uid);if(!$o)return page('订单不存在','<div class="empty">订单不存在或无权查看。</div>',$config);$events=order_timeline($service->events($o['id']),$o);$tempSubscription='';if(!empty($o['temporary_subscription_url'])){$active=$o['temporary_subscription_status']==='active';$tempSubscription='<section class="temporary-subscription '.($active?'temporary-active':'temporary-revoked').'" id="temporary-subscription"><div><span class="order-section-label">TEMPORARY SUBSCRIPTION</span><h2>临时订阅地址</h2><p>'.($active?'付款已确认，人工发货前可临时使用。正式发货后此地址会自动失效。':'该临时订阅地址已失效，请使用下方正式订阅地址。').'</p></div><div class="temporary-link-row"><code id="temporary-subscription-link">'.e($o['temporary_subscription_url']).'</code>'.($active?'<button type="button" class="copy-subscription" data-copy-target="temporary-subscription-link">复制</button>':'<span class="temporary-revoked-label">已失效</span>').'</div></section>';}$actions='';if(in_array($o['status'],array('pending_payment','pending_delivery','delivered'),true))$actions.='<form method="post" action="/orders/'.$no.'/cancel">'.csrf_field().'<label>取消原因<textarea name="reason" required maxlength="500"></textarea></label><button class="secondary-button">取消订单</button></form>';if(in_array($o['status'],array('pending_delivery','delivered'),true))$actions.='<form method="post" action="/orders/'.$no.'/refund">'.csrf_field().'<label>退款原因<textarea name="reason" required maxlength="500"></textarea></label><button class="secondary-button">申请退款</button></form>';$delivery='';if($o['status']==='delivered'){$s=$pdo->prepare('SELECT * FROM delivery_records WHERE order_id=(SELECT id FROM orders WHERE order_no=?) AND is_current=1');$s->execute(array($no));$d=$s->fetch();if($d){$c=new CryptoService($config);$x=json_decode($c->decrypt($d['content_ciphertext'],$d['content_nonce'],$d['content_tag']),true);$delivery='<div class="delivery"><h2>交付内容</h2><p class="subscription-row"><b>订阅链接：</b><span class="subscription-value"><code id="subscription-link">'.e($x['subscription']).'</code><button type="button" class="copy-subscription" data-copy-target="subscription-link">复制</button></span></p><p><b>账号信息：</b>'.nl2br(e($x['account'])).'</p><p><b>开通时间：</b>'.e($x['opened_at']).'　<b>到期时间：</b>'.e($x['expires_at']).'</p><p><b>使用说明：</b>'.nl2br(e($x['instructions'])).'</p></div>';}} $paymentBox='';if($o['status']==='pending_payment'){$ps=(new PaymentService($pdo,$config))->settings();if(!empty($ps['enabled'])){$paymentBox='<section class="order-payment-note"><span>￥</span><div><b>在线支付</b><p>选择支付方式完成付款，支付成功后系统会自动确认并发放临时订阅。</p>'.(!empty($ps['alipay_enabled'])?'<a class="button" href="/payment/start/'.e($no).'/alipay">支付宝支付</a> ':'').(!empty($ps['wechat_enabled'])?'<a class="secondary-button" href="/payment/start/'.e($no).'/wxpay">微信支付</a>':'').'</div></section>';}}$statusLabel=status_text($o['status']);$statusClass='order-status-'.e($o['status']);$actions='';$timeline='<section class="order-timeline-card">'.$events.'</section>';$delivery=$delivery?str_replace('<div class="delivery">','<section class="order-delivery-card"><div class="order-section-heading"><div><span class="order-section-label">SECURE DELIVERY</span><h2>交付内容</h2></div><span class="delivery-safe">已加密保护</span></div><div class="order-delivery-body">',str_replace('</div>','</div></section>',$delivery)):'';page('订单详情','<div class="order-detail-page"><a class="order-back-link" href="/orders">← 返回我的订单</a><section class="order-detail-card"><header class="order-detail-header"><div class="order-header-icon">✦</div><div class="order-header-copy"><span class="eyebrow">ORDER / '.e($o['order_no']).'</span><h1>'.e($o['product_name_snapshot']).'</h1><p>创建于 '.e($o['created_at']).'</p></div><span class="order-status-badge '.$statusClass.'"><i></i>'.e($statusLabel).'</span></header><div class="order-summary-grid"><div><span>购买方案</span><b>'.e($o['plan_name_snapshot']).'</b><small>'.(int)$o['duration_days_snapshot'].' 天有效期</small></div><div><span>订单金额</span><b class="order-amount">'.money($o['total_amount_cents']).'</b><small>人工确认付款</small></div><div><span>订单编号</span><b class="order-number">'.e($o['order_no']).'</b><small>请妥善保存</small></div></div>'.($paymentBox?:'<div class="order-payment-note"><span>◷</span><p>付款由管理员人工确认，确认后将进入发货队列。订单状态变化会同步显示在下方时间线中。需要退款或处理其他售后问题，请前往 <a href="/tickets">售后工单</a> 提交申请。</p></div>').'</section>'.$actions.$delivery.$tempSubscription.$timeline.copy_subscription_script().'</div>',$config);});
