$router->get('/account', function() use($config,$pdo){$uid=Security::requireUser();$s=$pdo->prepare('SELECT * FROM users WHERE id=?');$s->execute(array($uid));$u=$s->fetch();$orders=$pdo->prepare('SELECT COUNT(*) FROM orders WHERE user_id=?');$orders->execute(array($uid));$pending=$pdo->prepare('SELECT COUNT(*) FROM orders WHERE user_id=? AND status IN ("pending_payment","pending_delivery","refunding")');$pending->execute(array($uid));$n=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 5');$n->execute(array($uid));$notes='';foreach($n as $item)$notes.='<div class="notification-item '.($item['read_at']?'':'unread').'">'.e($item['title']).'<small>'.e($item['created_at']).'</small><p>'.e($item['content']).'</p></div>';$body='<div class="account-page"><div class="section-head"><h1>个人中心</h1></div><div class="account-grid"><section class="form-card"><h2>账户资料</h2><p>邮箱：'.e($u['email']).'</p><p>注册时间：'.e($u['created_at']).'</p><p>订单总数：'.(int)$orders->fetchColumn().'　待处理：'.(int)$pending->fetchColumn().'</p><form method="post" action="/account/profile">'.csrf_field().'<label>昵称<input name="display_name" maxlength="100" value="'.e($u['display_name']).'" required></label><button class="button">保存资料</button></form></section><section class="form-card"><h2>修改密码</h2><form method="post" action="/account/password">'.csrf_field().'<label>旧密码<input type="password" name="old_password" required></label><label>新密码<input type="password" name="new_password" minlength="8" required></label><button class="button">更新密码</button></form></section></div><section class="form-card"><div class="section-head"><h2>最近通知</h2><a href="/notifications">查看全部</a></div>'.($notes?:'<div class="empty">暂无通知。</div>').'</section></div>';page('个人中心',$body,$config);});
$router->post('/account/profile', function() use($config,$pdo){$uid=Security::requireUser();post_csrf();$name=trim(isset($_POST['display_name'])?$_POST['display_name']:'');if($name===''||strlen($name)>100){flash('error','昵称长度必须为 1-100 个字符。');}else{$pdo->prepare('UPDATE users SET display_name=?,updated_at=? WHERE id=?')->execute(array($name,date('Y-m-d H:i:s'),$uid));$_SESSION['user_name']=$name;flash('success','资料已更新。');}redirect('/account');});
$router->post('/account/password', function() use($config,$pdo){$uid=Security::requireUser();post_csrf();$s=$pdo->prepare('SELECT password_hash FROM users WHERE id=?');$s->execute(array($uid));$u=$s->fetch();if(!$u||!password_verify(isset($_POST['old_password'])?$_POST['old_password']:'',$u['password_hash'])||strlen(isset($_POST['new_password'])?$_POST['new_password']:'')<8){flash('error','旧密码不正确或新密码少于 8 位。');}else{$pdo->prepare('UPDATE users SET password_hash=?,updated_at=? WHERE id=?')->execute(array(password_hash($_POST['new_password'],PASSWORD_DEFAULT),date('Y-m-d H:i:s'),$uid));session_regenerate_id(true);$_SESSION['user_id']=$uid;$_SESSION['user_name']=isset($_SESSION['user_name'])?$_SESSION['user_name']:'';flash('success','密码已更新，请妥善保管。');}redirect('/account');});
$router->get('/notifications', function() use($config,$pdo){$uid=Security::requireUser();$s=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY id DESC');$s->execute(array($uid));$rows='';foreach($s as $n)$rows.='<div class="notification-item '.($n['read_at']?'':'unread').'" data-id="'.(int)$n['id'].'"><b>'.e($n['title']).'</b><small>'.e($n['created_at']).'</small><p>'.e($n['content']).'</p>'.(!$n['read_at']?'<form method="post" action="/notifications/'.$n['id'].'/read">'.csrf_field().'<button class="row-link">标记已读</button></form>':'').'</div>';$body='<div class="notifications-page"><div class="section-head"><h1>站内通知</h1><form method="post" action="/notifications/read-all">'.csrf_field().'<button class="secondary-button">全部标记已读</button></form></div>'.($rows?:'<div class="empty">暂无通知。</div>').'</div>';page('站内通知',$body,$config);});
$router->post('/notifications/{id}/read', function($id) use($config,$pdo){$uid=Security::requireUser();post_csrf();$pdo->prepare('UPDATE notifications SET read_at=? WHERE id=? AND user_id=? AND read_at IS NULL')->execute(array(date('Y-m-d H:i:s'),(int)$id,$uid));redirect('/notifications');});
$router->post('/notifications/read-all', function() use($config,$pdo){$uid=Security::requireUser();post_csrf();$pdo->prepare('UPDATE notifications SET read_at=? WHERE user_id=? AND read_at IS NULL')->execute(array(date('Y-m-d H:i:s'),$uid));redirect('/notifications');});
$router->get('/tickets', function() use($config,$pdo){$uid=Security::requireUser();$s=$pdo->prepare('SELECT * FROM support_tickets WHERE user_id=? ORDER BY id DESC');$s->execute(array($uid));$statusLabels=array('open'=>'处理中','waiting_customer'=>'等待回复','closed'=>'已关闭');$rows='';$count=0;foreach($s as $t){$count++;$state=isset($statusLabels[$t['status']])?$statusLabels[$t['status']]:$t['status'];$rows.='<tr><td><a class="support-ticket-no" href="/tickets/'.$t['id'].'">'.e($t['ticket_no']).'</a></td><td><a class="support-subject" href="/tickets/'.$t['id'].'">'.e($t['subject']).'<small>查看工单详情 →</small></a></td><td><span class="support-status support-status-'.e($t['status']).'"><i></i>'.e($state).'</span></td><td><time>'.e($t['updated_at']).'</time></td></tr>';}$body='<div class="support-page"><section class="support-hero"><div><span class="eyebrow">CUSTOMER SUPPORT</span><h1>售后工单</h1><p>遇到使用问题？提交工单，我们会尽快为你处理。</p></div><div class="support-hero-badge"><span>✦</span><b>专属客服支持</b><small>工作日通常在 10 分钟内响应</small></div></section><div class="support-layout"><section class="support-create-card"><div class="support-card-heading"><div class="support-icon">＋</div><div><h2>提交新工单</h2><p>请尽量描述清楚你遇到的问题，方便我们快速定位。</p></div></div><form method="post" action="/tickets">'.csrf_field().'<label>主题<input name="subject" maxlength="200" required placeholder="例如：订阅无法连接、订单交付问题"></label><label>问题描述<textarea name="body" maxlength="5000" required placeholder="请描述问题发生的时间、设备和具体表现"></textarea></label><div class="support-form-footer"><small>提交后可在下方查看处理进度</small><button class="button" type="submit">提交工单 <span>→</span></button></div></form></section><aside class="support-help-card"><span class="support-help-icon">?</span><h3>提交前可以先看看</h3><p>如果是客户端安装、订阅导入等问题，可以先查看使用教程，很多常见问题都有解决方案。</p><a href="/articles">查看使用教程 <span>↗</span></a></aside></div><section class="support-list-card"><div class="support-list-heading"><div><span class="support-label">我的请求</span><h2>工单记录</h2></div><span class="support-count">共 '.(int)$count.' 个工单</span></div><div class="table-wrap support-table-wrap"><table><thead><tr><th>工单编号</th><th>主题</th><th>状态</th><th>最后更新</th></tr></thead><tbody>'.($rows?:'<tr><td colspan="4"><div class="support-empty"><span>☷</span><b>还没有提交过工单</b><small>遇到问题时，可以从上方创建第一张工单。</small></div></td></tr>').'</tbody></table></div></section></div>';page('售后工单',$body,$config);});
$router->post('/tickets', function() use($config,$pdo){$uid=Security::requireUser();post_csrf();$now=date('Y-m-d H:i:s');$no='TKT'.date('YmdHis').strtoupper(bin2hex(random_bytes(3)));$pdo->beginTransaction();$pdo->prepare('INSERT INTO support_tickets(ticket_no,user_id,subject,created_at,updated_at) VALUES(?,?,?,?,?)')->execute(array($no,$uid,substr(trim($_POST['subject']),0,200),$now,$now));$id=$pdo->lastInsertId();$pdo->prepare('INSERT INTO ticket_messages(ticket_id,sender_type,sender_user_id,body,created_at) VALUES(?,"user",?,?,?)')->execute(array($id,$uid,substr(trim($_POST['body']),0,5000),$now));$pdo->commit();flash('success','工单已提交。');redirect('/tickets/'.$id);});
$router->get('/tickets/{id}', function($id) use($config,$pdo){$uid=Security::requireUser();$s=$pdo->prepare('SELECT * FROM support_tickets WHERE id=? AND user_id=?');$s->execute(array((int)$id,$uid));$t=$s->fetch();if(!$t)return page('工单不存在','<div class="empty">工单不存在或无权查看。</div>',$config);$statusLabels=array('open'=>'处理中','waiting_customer'=>'等待回复','closed'=>'已关闭');$state=isset($statusLabels[$t['status']])?$statusLabels[$t['status']]:$t['status'];$s=$pdo->prepare('SELECT * FROM ticket_messages WHERE ticket_id=? ORDER BY id');$s->execute(array($t['id']));$msgs='';foreach($s as $m){$mine=$m['sender_type']!=='admin';$msgs.='<div class="support-message '.($mine?'support-message-user':'support-message-admin').'"><div class="support-message-avatar">'.($mine?'我':'客').'</div><div class="support-message-content"><div class="support-message-meta"><b>'.($mine?'我':'客服').'</b><time>'.e($m['created_at']).'</time></div><p>'.nl2br(e($m['body'])).'</p></div></div>';}$reply=$t['status']==='closed'?'<div class="support-closed-note"><span>✓</span> 该工单已关闭，如需继续咨询，请重新提交工单。</div>':'<form class="support-reply-form" method="post">'.csrf_field().'<label>追加说明<textarea name="body" required placeholder="请输入你想补充的内容"></textarea></label><div class="support-form-footer"><small>客服会在收到消息后尽快回复</small><button class="button" type="submit">发送消息 <span>→</span></button></div></form>';$body='<div class="support-detail-page"><a class="support-back-link" href="/tickets">← 返回工单列表</a><section class="support-detail-card"><header class="support-detail-header"><div><span class="eyebrow">TICKET / '.e($t['ticket_no']).'</span><h1>'.e($t['subject']).'</h1><p>最后更新于 '.e($t['updated_at']).'</p></div><span class="support-status support-status-'.e($t['status']).'"><i></i>'.e($state).'</span></header><div class="support-conversation">'.$msgs.'</div>'.$reply.'</section></div>';page('工单详情',$body,$config);});
$router->post('/tickets/{id}', function($id) use($config,$pdo){$uid=Security::requireUser();post_csrf();$s=$pdo->prepare('SELECT id FROM support_tickets WHERE id=? AND user_id=? AND status<>"closed"');$s->execute(array((int)$id,$uid));if(!$s->fetch())return page('工单不可用','<div class="empty">工单不存在或已关闭。</div>',$config);$now=date('Y-m-d H:i:s');$pdo->prepare('INSERT INTO ticket_messages(ticket_id,sender_type,sender_user_id,body,created_at) VALUES(?,"user",?,?,?)')->execute(array((int)$id,$uid,substr(trim($_POST['body']),0,5000),$now));$pdo->prepare('UPDATE support_tickets SET updated_at=?,status="open" WHERE id=?')->execute(array($now,(int)$id));redirect('/tickets/'.$id);});
