$router->post('/admin/login', function() use($config,$pdo){post_csrf();$s=$pdo->prepare('SELECT * FROM admin_users WHERE email=? AND status="active"');$s->execute(array(trim($_POST['email'])));$a=$s->fetch();if(!$a||!password_verify($_POST['password'],$a['password_hash'])){flash('error','管理员账号或密码错误。');return redirect('/admin/login');}session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$_SESSION['admin_name']=$a['display_name'];redirect('/admin');});
