$router->get('/admin/orders', function() use($config,$pdo){Security::requireAdmin();$status=isset($_GET['status'])?$_GET['status']:'';$q=isset($_GET['q'])?trim($_GET['q']):'';$from=isset($_GET['from'])?trim($_GET['from']):'';$to=isset($_GET['to'])?trim($_GET['to']):'';$min=isset($_GET['min_amount'])?trim($_GET['min_amount']):'';$max=isset($_GET['max_amount'])?trim($_GET['max_amount']):'';$allowed=array('pending_payment','pending_delivery','delivered','cancelled','refunding','refunded');$where=array('1=1');$args=array();if(in_array($status,$allowed,true)){$where[]='o.status=?';$args[]=$status;}if($q){$where[]='(o.order_no LIKE ? OR o.product_name_snapshot LIKE ? OR u.email LIKE ?)';$args[]='%'.$q.'%';$args[]='%'.$q.'%';$args[]='%'.$q.'%';}if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)){$where[]='o.created_at>=?';$args[]=$from.' 00:00:00';}if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)){$where[]='o.created_at<=?';$args[]=$to.' 23:59:59';}if(is_numeric($min)){$where[]='o.total_amount_cents>=?';$args[]=(int)round($min*100);}if(is_numeric($max)){$where[]='o.total_amount_cents<=?';$args[]=(int)round($max*100);}$s=$pdo->prepare('SELECT o.*,u.email FROM orders o JOIN users u ON u.id=o.user_id WHERE '.implode(' AND ',$where).' ORDER BY o.id DESC');$s->execute($args);$rows='';foreach($s as $o){$can=$o['status']==='pending_payment'||$o['status']==='pending_delivery'||$o['status']==='refunding';$rows.='<tr><td><input type="checkbox" name="order_ids[]" value="'.(int)$o['id'].'"'.($can?'':' disabled').'></td><td><a href="/admin/orders/'.e($o['order_no']).'">'.e($o['order_no']).'</a></td><td>'.e($o['email']).'</td><td>'.e($o['product_name_snapshot']).'<small class="table-sub">'.e($o['plan_name_snapshot']).' · '.(int)$o['duration_days_snapshot'].'天</small></td><td>'.money($o['total_amount_cents']).'</td><td><span class="status">'.status_text($o['status']).'</span></td></tr>';}$filters='<form class="filter admin-order-filter" method="get"><input name="q" placeholder="订单号 / 套餐 / 用户邮箱" value="'.e($q).'" ><select name="status"><option value="">全部状态</option><option value="pending_payment"'.($status==='pending_payment'?' selected':'').'>待付款确认</option><option value="pending_delivery"'.($status==='pending_delivery'?' selected':'').'>待发货</option><option value="delivered"'.($status==='delivered'?' selected':'').'>已发货</option><option value="refunding"'.($status==='refunding'?' selected':'').'>退款中</option><option value="refunded"'.($status==='refunded'?' selected':'').'>已退款</option><option value="cancelled"'.($status==='cancelled'?' selected':'').'>已取消</option></select><input type="date" name="from" value="'.e($from).'" title="开始日期"><input type="date" name="to" value="'.e($to).'" title="结束日期"><input type="number" name="min_amount" step="0.01" min="0" placeholder="最低金额" value="'.e($min).'" ><input type="number" name="max_amount" step="0.01" min="0" placeholder="最高金额" value="'.e($max).'" ><button>筛选</button></form>';$body='<div class="section-head"><div><h1>订单管理</h1><p>支持按订单、套餐、用户、状态、日期和金额筛选，并批量处理。</p></div></div>'.$filters.'<form method="post" action="/admin/orders/batch" onsubmit="return document.querySelectorAll(\"input[name=\\\"order_ids[]\\\"]:checked\").length>0"><input type="hidden" name="_csrf" value="'.e(Security::csrfToken()).'"><div class="batch-toolbar"><label><input type="checkbox" id="check-all"> 全选</label><select name="action" required><option value="">批量操作</option><option value="confirm_payment">确认付款</option><option value="cancel">取消订单</option><option value="refund_approve">同意退款</option><option value="refund_reject">拒绝退款</option></select><input name="reason" placeholder="取消/退款处理说明（批量时必填）" maxlength="500"><button class="button" type="submit">执行</button></div><div class="table-wrap"><table><tr><th></th><th>订单号</th><th>用户</th><th>套餐</th><th>金额</th><th>状态</th></tr>'.$rows.'</table></div></form><script>var all=document.getElementById("check-all");if(all)all.onclick=function(){document.querySelectorAll("input[name=\"order_ids[]\"]:not(:disabled)").forE