ss="secondary-button">取消订单</button></form>';if($o['status']==='pending_delivery')$actions.='<form method="post" action="/admin/orders/'.$no.'/deliver"><h3>人工发货</h3>'.csrf_field().'<label>订阅链接<input name="subscription" required></label><label>账号信息（可选）<textarea name="account"></textarea></label><label>开通时间<input type="datetime-local" name="opened_at" required></label><label>到期时间<input type="datetime-local" name="expires_at" required></label><label>使用说明（可选）<textarea name="instructions"></textarea></label><button class="button">保存并发货</button></form>';if($o['status']==='refunding')$actions.='<form method="post" action="/admin/orders/'.$no.'/refund"><h3>处理退款申请</h3>'.csrf_field().'<label>处理说明<textarea name="reason" required></textarea></label><button class="button" name="decision" value="approve">同意退款</button> <button class="secondary-button" name="decision" value="reject">拒绝退款</button></form>';page('订单处理','<div class="detail"><span class="eyebrow">'.e($o['order_no']).'</span><h1>'.e($o['product_name_snapshot']).'</h1><p>用户：'.e($o['email']).'</p><p>购买方案：'.e($o['plan_name_snapshot']).' · '.(int)$o['duration_days_snapshot'].'天</p><p>金额：'.money($o['total_amount_cents']).'</p><p>状态：'.status_text($o['status']).'</p><hr>'.$actions.$editDelivery.order_timeline($service->events($o['id']),$o).'</div>',$config);});
