function product_plans_input(){
    $input=isset($_POST['plans'])&&is_array($_POST['plans'])?$_POST['plans']:array();if(!$input)throw new InvalidArgumentException('请至少添加一个时长价格方案。');$plans=array();$names=array();
    foreach($input as $item){if(!is_array($item))throw new InvalidArgumentException('方案格式无效。');$name=trim(isset($item['name'])?$item['name']:'');$days=filter_var(isset($item['duration_days'])?$item['duration_days']:'',FILTER_VALIDATE_INT);$priceText=trim(isset($item['price'])?$item['price']:'');$sort=filter_var(isset($item['sort_order'])?$item['sort_order']:'0',FILTER_VALIDATE_INT);$status=isset($item['status'])?$item['status']:'inactive';if($name===''||strlen($name)>100||$days===false||$days<1||$days>36500||!preg_match('/^\\d{1,8}(?:\\.\\d{1,2})?$/',$priceText)||$sort===false||$sort<0||!in_array($status,array('active','inactive'),true))throw new InvalidArgumentException('请检查方案名称、有效天数和价格。');$parts=explode('.',$priceText);$cents=((int)$parts[0])*100+(int)str_pad(isset($parts[1])?$parts[1]:'',2,'0');if($cents<1)throw new InvalidArgumentException('方案价格必须大于 0。');$key=function_exists('mb_strtolower')?mb_strtolower($name,'UTF-8'):strtolower($name);if(isset($names[$key]))throw new InvalidArgumentException('同一套餐内的方案名称不能重复。');$names[$key]=true;$plans[]=array('id'=>isset($item['id'])?(int)$item['id']:0,'name'=>$name,'duration_days'=>$days,'price_cents'=>$cents,'status'=>$status,'sort_order'=>$sort);}
    return $plans;
}
function save_product_plans($pdo,$productId,$plans,$now){
    $seen=array();foreach($plans as $plan){if($plan['id']>0){$s=$pdo->prepare('UPDATE product_plans SET name=?,duration_days=?,price_cents=?,status=?,sort_order=?,updated_at=? WHERE id=? AND product_id=?');$s->execute(array($plan['name'],$plan['duration_days'],$plan['price_cents'],$plan['status'],$plan['sort_order'],$now,$plan['id'],$productId));if(!$s->rowCount()){$check=$pdo->prepare('SELECT id FROM product_plans WHERE id=? AND product_id=?');$check->execute(array($plan['id'],$productId));if(!$check->fetch())throw new InvalidArgumentException('提交的方案不属于当前套餐。');}$seen[]=$plan['id'];}else{$pdo->prepare('INSERT INTO product_plans(product_id,name,duration_days,price_cents,status,sort_order,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)')->execute(array($productId,$plan['name'],$plan['duration_days'],$plan['price_cents'],$plan['status'],$plan['sort_order'],$now,$now));$seen[]=(int)$pdo->lastInsertId();}}
    $s=$pdo->prepare('SELECT id FROM product_plans WHERE product_id=?');$s->execute(array($productId));foreach($s->fetchAll() as $row){if(!in_array((int)$row['id'],$seen,true)){$c=$pdo->prepare('SELECT COUNT(*) FROM orders WHERE product_plan_id=?');$c->execute(array($row['id']));if((int)$c->fetchColumn())$pdo->prepare('UPDATE product_plans SET status="inactive",updated_at=? WHERE id=?')->execute(array($now,$row['id']));else $pdo->prepare('DELETE FROM product_plans WHERE id=?')->execute(array($row['id']));}}
    $first=$pdo->prepare('SELECT duration_days,price_cents FROM product_plans WHERE product_id=? ORDER BY status="active" DESC,sort_order,id LIMIT 1');$first->execute(array($productId));$mirror=$first->fetch();if($mirror)$pdo->prepare('UPDATE products SET duration_days=?,price_cents=? WHERE id=?')->execute(array($mirror['duration_days'],$mirror['price_cents'],$productId));
}
function product_input(){
    $name=trim(isset($_POST['name'])?$_POST['name']:''); $description=trim(isset($_POST['description'])?$_POST['description']:''); $traffic=trim(isset($_POST['traffic'])?$_POST['traffic']:''); $region=trim(isset($_POST['region'])?$_POST['region']:''); $devices=filter_var(isset($_POST['device_limit'])?$_POST['device_limit']:'',FILTER_VALIDATE_INT); $sort=filter_var(isset($_POST['sort_order'])?$_POST['sort_order']:'0',FILTER_VALIDATE_INT); $status=isset($_POST['status'])?$_POST['status']:'draft';
    if($name===''||strlen($name)>160||$description===''||strlen($description)>5000||$traffic===''||strlen($traffic)>100||$region===''||strlen($region)>100||$devices===false||$devices<1||$devices>999||$sort===false||$sort<0||!in_array($status,array('draft','active','inactive'),true)) throw new InvalidArgumentException('请完整填写套餐信息，并检查设备数和排序范围。');
    return array('name'=>$name,'description'=>$description,'traffic'=>$traffic,'region'=>$region,'device_limit'=>$devices,'sort_order'=>$sort,'status'=>$status);
}
$router->get('/admin/products/create', function() use($config){Security::requireAdmin();page('新建套餐',product_form(null,'/admin/products/create','新建套餐'),$config);});
$router->post('/admin/products/create', function() use($config,$pdo){$aid=Security::requireAdmin();post_csrf();try{$p=product_input();$plans=product_plans_input();if($p['status']==='active'&&!count(array_filter($plans,function($x){return $x['status']==='active';})))throw new InvalidArgumentException('上架套餐至少需要一个启用的时长方案。');$pdo->beginTransaction();$now=date('Y-m-d H:i:s');$first=$plans[0];$pdo->prepare('INSERT INTO products(name,description,traffic,region,device_limit,duration_days,price_cents,status,sort_order,created_by,updated_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute(array($p['name'],$p['description'],$p['traffic'],$p['region'],$p['device_limit'],$first['duration_days'],$first['price_cents'],$p['status'],$p['sort_order'],$aid,$aid,$now,$now));$id=$pdo->lastInsertId();save_product_plans($pdo,$id,$plans,$now);$pdo->commit();flash('success','套餐及期限价格方案已创建。');redirect('/admin/products');}catch(Exception $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());redirect('/admin/products/create');}});
