$router->post('/admin/products/{id}/edit', function($id) use($config,$pdo){$aid=Security::requireAdmin();post_csrf();try{$p=product_input();$plans=product_plans_input();if($p['status']==='active'&&!count(array_filter($plans,function($x){return $x['status']==='active';})))throw new InvalidArgumentException('上架套餐至少需要一个启用的时长方案。');$pdo->beginTransaction();$lock=$pdo->prepare('SELECT id FROM products WHERE id=? FOR UPDATE');$lock->execute(array((int)$id));if(!$lock->fetch())throw new InvalidArgumentException('套餐不存在。');$now=date('Y-m-d H:i:s');$s=$pdo->prepare('UPDATE products SET name=?,description=?,traffic=?,region=?,device_limit=?,status=?,sort_order=?,updated_by=?,updated_at=? WHERE id=?');$s->execute(array($p['name'],$p['description'],$p['traffic'],$p['region'],$p['device_limit'],$p['status'],$p['sort_order'],$aid,$now,(int)$id));save_product_plans($pdo,(int)$id,$plans,$now);$pdo->commit();flash('success','套餐和期限方案已更新，历史订单快照不受影响。');redirect('/admin/products');}catch(Exception $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());redirect('/admin/products/'.$id.'/edit');}});
$router->post('/admin/products/{id}/toggle', function($id) use($config,$pdo){$aid=Security::requireAdmin();post_csrf();$s=$pdo->prepare('SELECT status FROM products WHERE id=?');$s->execute(array((int)$id));$p=$s->fetch();if(!$p){flash('error','套餐不存在。');return redirect('/admin/products');}$next=$p['status']==='active'?'inactive':'active';$pdo->prepare('UPDATE products SET status=?,updated_by=?,updated_at=? WHERE id=?')->execute(array($next,$aid,date('Y-m-d H:i:s'),(int)$id));flash('success',$next==='active'?'套餐已上架。':'套餐已下架，历史订单不受影响。');redirect('/admin/products');});
$router->post('/admin/products/{id}/delete', function($id) use($config,$pdo){Security::requireAdmin();post_csrf();$s=$pdo->prepare('SELECT COUNT(*) FROM orders WHERE product_id=?');$s->execute(array((int)$id));if((int)$s->fetchColumn()>0){flash('error','该套餐已有订单使用，不能删除；如需停止销售请下架。');return redirect('/admin/products');}$s=$pdo->prepare('DELETE FROM products WHERE id=?');$s->execute(array((int)$id));flash('success','套餐已删除。');redirect('/admin/products');});
$router->get('/admin/products', function() use($config,$pdo){Security::requireAdmin();$q=trim(isset($_GET['q'])?$_GET['q']:'');$status=isset($_GET['status'])?$_GET['status']:'';$where=array('1=1');$args=array();if($q){$where[]='(name LIKE ? OR region LIKE ? OR traffic LIKE ?)';$args[]='%'.$q.'%';$args[]='%'.$q.'%';$args[]='%'.$q.'%';}if(in_array($status,array('draft','active','inactive'),true)){$where[]='status=?';$args[]=$status;}$s=$pdo->prepare('SELECT * FROM products WHERE '.implode(' AND ',$where).' ORDER BY sort_order ASC,id DESC');$s->execute($args);$rows='';foreach($s as $p){$state=$p['status']==='active'?'已上架':($p['status']==='inactive'?'已下架':'草稿');$action=$p['status']==='active'?'下架':'上架';$ps=$pdo->prepare('SELECT name,duration_days,price_cents FROM product_plans WHERE product_id=? AND status="active" ORDER BY sort_order,id');$ps->execute(array($p['id']));$summary=array();foreach($ps as $x)$summary[]=e($x['name']).' '.(int)$x['duration_days'].'天 '.money($x['price_cents']);$rows.='<tr><td><div class="product-name"><b>'.e($p['name']).'</b><small>'.e($p['region']).' · '.e($p['traffic']).'</small></div></td><td><div class="product-plans-summary">'.($summary?implode('<br>',$summary):'暂无启用方案').'</div></td><td>'.e($p['device_limit']).' 台</td><td><span class="admin-status product-'.$p['status'].'">'.$state.'</span></td><td>'.(int)$p['sort_order'].'</td><td><div class="row-actions"><a class="row-edit" href="/admin/products/'.$p['id'].'/edit">编辑方案</a><form method="post" action="/admin/products/'.$p['id'].'/toggle" class="inline">'.csrf_field().'<button class="row-link" type="submit">'.$action.'</button></form><form method="post" action="/admin/products/'.$p['id'].'/delete" class="inline" data-confirm="确定删除这个套餐吗？">'.csrf_field().'<button class="row-danger" type="submit">删除</button></form></div></td></tr>';}$rows=$rows?:'<tr><td colspan="6" class="admin-empty">没有找到符合条件的套餐。</td></tr>';page('套餐管理','<div class="catalog-heading"><div><span class="admin-kicker">CATALOG / 套餐管理</span><h1>套餐管理</h1><p>管理套餐及其多个时长、价格和销售状态。</p></div><a class="button" href="/admin/products/create">＋ 新建套餐</a></div><section class="admin-panel catalog-panel"><form class="catalog-toolbar" method="get"><div class="catalog-search">⌕<input name="q" value="'.e($q).'" placeholder="搜索套餐名称、地区或流量"></div><select name="status"><option value="">全部状态</option><option value="active"'.($status==='active'?' selected':'').'>已上架</option><option value="inactive"'.($status==='inactive'?' selected':'').'>已下架</option><option value="draft"'.($status==='draft'?' selected':'').'>草稿</option></select><button class="filter-button" type="submit">筛选</button>'.($q||$status?'<a class="clear-filter" href="/admin/products">清除条件</a>':'').'</form><div class="table-wrap catalog-table-wrap"><table class="admin-table catalog-table"><thead><tr><th>套餐名称</th><th>可购方案（期限 / 价格）</th><th>设备数</th><th>状态</th><th>排序</th><th>操作</th></tr></thead><tbody>'.$rows.'</tbody></table></div></section>',$config);});
function article_input(){
    $title=trim(isset($_POST['title'])?$_POST['title']:'');$category=trim(isset($_POST['category'])?$_POST['category']:'使用教程');$summary=trim(isset($_POST['summary'])?$_POST['summary']:'');$content=trim(isset($_POST['content'])?$_POST['content']:'');$cover=isset($_POST['cover_style'])?$_POST['cover_style']:'blue';$status=isset($_POST['status'])?$_POST['status']:'draft';
    if($title===''||strlen($title)>200||!in_array($category,array('公益节点','使用教程','常见问题'),true)||strlen($summary)>500||$content===''||strlen($content)>60000||!in_array($cover,array('blue','purple','orange'),true)||!in_array($status,array('draft','published','offline'),true))throw new InvalidArgumentException('请完整填写文章内容并检查字段范围。');
    return array('title'=>$title,'category'=>$category,'summary'=>$summary,'content'=>$content,'cover_style'=>$cover,'status'=>$status);
}
