'').'>已下架</option></select><button class="filter-button" type="submit">筛选</button></form><div class="table-wrap catalog-table-wrap"><table class="admin-table catalog-table article-admin-table"><thead><tr><th>文章标题</th><th>摘要</th><th>状态</th><th>操作</th></tr></thead><tbody>'.($rows?:'<tr><td colspan="4" class="admin-empty">还没有文章。</td></tr>').'</tbody></table></div></section>';page('文章管理',$body,$config);});
